interface RateLimiter {
  allow(key: string, permits: number): boolean;
}
class Registry {
  private store = new Map<string, () => RateLimiter>();
  register(name: string, factory: () => RateLimiter) { this.store.set(name, factory); }
  resolve(name: string, ...ctx: any[]): RateLimiter {
    const f = this.store.get(name); if (!f) throw new Error('Unknown limiter');
    return f();
  }
}
