interface Parser {
  parse(input: AsyncIterable<Uint8Array>): AsyncIterable<Record<string, unknown>>;
}

type ParserFactory = () => Parser;

class Registry {
  private factories = new Map<string, ParserFactory>();

  register(extension: string, factory: ParserFactory): void {
    this.factories.set(extension.toLowerCase(), factory);
  }

  getParser(extension: string): Parser | undefined {
    return this.factories.get(extension.toLowerCase())?.();
  }
}

// Usage example
const registry = new Registry();
registry.register('xml', () => new XmlParser());
registry.register('yaml', () => new YamlParser());
registry.register('avro', () => new AvroParser());

async function processFile(path: string, data: AsyncIterable<Uint8Array>) {
  const ext = path.split('.').pop();
  const parser = registry.getParser(ext);
  if (!parser) throw new Error(`Unsupported format: ${ext}`);

  for await (const record of parser.parse(data)) {
    // Process record with backpressure handling
    await processRecord(record);
  }
}
```

## Why This Is Asked

Tests ability to design an extensible plugin mechanism using simple interfaces and a runtime registry.

## Key Concepts

- Registry pattern for dynamic extension
- Conflict resolution via priority or timestamp
- Preconditions gating and graceful fallbacks

## Code Example

```ts
interface Command {
  id: string
  name: string
  prerequisites?: string[]
  execute(ctx: any): void
}

class Registry {
  private map = new Map<string, {cmd: Command, priority: number, ts: number}>();
  register(cmd: Command, priority = 0){
    this.map.set(cmd.name, {cmd, priority, ts: Date.now()});
  }
  dispatch(name: string, ctx: any){
    const entry = this.map.get(name);
    if(!entry) return;
    if((entry.cmd.prerequisites ?? []).some(p => !ctx.flags?.includes(p))) return;
    entry.cmd.execute(ctx);
  }
  unregister(name: string){ this.map.delete(name); }
  clear(){ this.map.clear(); }
}
``` 

